import type { QuestDef } from './quests';

/* =====================================================================================================
   OS CAMINHOS DOS POVOS NASCIDOS LONGE (25/10/2026) — anões e elfos, níveis 1–25
   Erling: "agora vamos criar o caminho dos anões e dos elfos (raça nascida que nascem em outras regiões)".
   Decidido: cada povo tem a sua campanha inteira, do 1 ao 25, andando pela sua metade do mapa,
   e as três (humanos, anões, elfos) se encontram em Askavik, na Chamada de Askavik.

   O CAMINHO DA FORJA (anões, nordeste):
     Brasaforja (1–8) → Ulfheim (9–11) → o passo de Midvangr (12–14) → Cinzalto e as Minas Afogadas (15–19)
     → a cachoeira de Kaldrfoss (20–21) → a Forja de Askavik e as Catacumbas (22–24) → o juramento da bigorna, em casa (25).
     Masmorras: Galerias de Brasaforja, Minas Afogadas, Catacumbas de Askavik. Instinto (Sentido da Pedra) em 10 missões.

   O CAMINHO DA MATA (elfos, oeste):
     Lithendel (1–9) → Vestheim (10–11) → Skógar e a Toca das Ratazanas (12–13) → os juncos de Mýrarvik (14–16)
     → Skjoldvik, na costa fria (17–18) → Hvítadalr (19–20) → a Cripta de Hemara (21–22) → a Grande Biblioteca de Askavik (23–24)
     → o juramento da folha, em casa (25). Masmorras: Raízes de Lithendel, Toca das Ratazanas Rubras, Cripta de Hemara.
     Instinto (Elo da Floresta) em 10 missões.

   Os níveis seguem os monstros de cada região (o berço dos anões é mais duro que o dos homens: diabretes e lobos gélidos
   rondam Brasaforja desde cedo). As pontes entre uma missão e outra ficam em RACE_BRIDGES; quem dá cada missão está
   de pé no mundo (campanha.ts, CAMPAIGN_NPCS).
   ===================================================================================================== */

const CF = 'Caminho da Forja', CM = 'Caminho da Mata';
const F = { who: 'Instinto', t: 'Aperte F (ou o terceiro olho, no menu de ações) para ligar o seu Instinto. O que esta missão pede só aparece para quem está atento.' };
export const BO = 'Thane Borin Barba-Longa', SG = 'Velha Sigrun', DV = 'Mestre-Mineiro Dvalin', BK = 'Mestre-Forjador Brokki', HJ = 'Ferreira Hjördis', TV = 'Guarda-Passo Torvald', EG = 'Capataz Eldgrim', UN = 'Barqueira Unn', KA = 'Mestre-Forjador Kári';
export const FA = 'Anciã Faelwen', AE = 'Aerin', SY = 'Patrulheira Sylwen', HU = 'Juíza Hulda', IV = 'Caçador Ivo', TO = 'Curandeira Tova', EY = 'Vigia Eyvind', RG = 'Pastora Ragnhild', OS = 'Cronista Ormund Salveth';

